```css
.pricing .cards {
  display: grid; grid-template-columns: repeat(3, 1fr); gap: 1rem;
}
@media (max-width: 900px) { .pricing .cards { grid-template-columns: repeat(2, 1fr); } }
@media (max-width: 600px) { .pricing .cards { grid-template-columns: 1fr; } }
#billing-toggle:checked ~ .cards .card .monthly { display:none; }
#billing-toggle:checked ~ .cards .card .yearly { display:block; }
.card { transform: translateY(6px); opacity:0; animation: fadeInUp 400ms ease forwards; }
@media (prefers-reduced-motion: reduce) { .card { animation: none; } }
@keyframes fadeInUp { to { transform: translateY(0); opacity:1; } }

/* accessibility focus */
.cta:focus-visible { outline: 2px solid #0b5bd3; outline-offset: 2px; }
```

